// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Read group and Marketplace feeds into scra JSONL records
// Flo: visit each feed_path_list page (halt checks apply) > read posts (role article) with permalink, author, text > one record per post > --live writes one .jsonl file atomically into scra's social-in folder; never clicks, never types
// I/O: Ctx + config feed_* (caller) > records count; file <feedd>/fb-<ms>.jsonl; scra ingest picks it up
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const post = @import("ru-post-main.zig"); const cfgz = @import("cf-conf-load.zig");
const CF = .{ .pre = "(function(){var f=document.querySelector('[role=feed]');return f?Array.from(f.children).filter(function(e){return e.innerText.trim().length>60}):Array.from(document.querySelectorAll('[role=article]'))})().slice(0,", .pos = ").map(function(e){var l=e.querySelector('a[href*=\"/posts/\"],a[href*=\"/permalink/\"],a[href*=\"/marketplace/item/\"]');var h=e.querySelector('h2,h3,h4')||e.querySelector('a[href*=\"/user/\"]');return JSON.stringify({u:l?l.getAttribute('href'):'',a:h?h.innerText.trim():'',t:e.innerText,f:document.querySelector('[role=feed]')?1:0})})", .part = ".part", .kind = "face", .role = "private", .rnds = 5, .gapz = 2500, .down = "window.scrollBy(0,1400),[]" };
const KEYS = [_][]const u8{ "/posts/", "/permalink/", "/item/" };
const HAVE = "(document.querySelector('a[href*=\"/posts/\"],a[href*=\"/permalink/\"],a[href*=\"/marketplace/item/\"]')||Array.from(document.querySelectorAll('[role=feed]>*')).some(function(e){return e.innerText.trim().length>60}))?['1']:[]";
const DIAG = "(function(){var n=function(s){return document.querySelectorAll(s).length};var keep=/^(groups|posts|permalink|user|photo|photos|commerce|listing|marketplace|item|videos|reel|watch|hashtag|photo\\.php|permalink\\.php)$/;var m={};document.querySelectorAll('[role=feed] a[href],[role=article] a[href]').forEach(function(a){var p=new URL(a.getAttribute('href'),location.href).pathname.split('/').filter(Boolean).map(function(s){return keep.test(s)?s:'*'}).join('/');m[p]=(m[p]||0)+1});var f=document.querySelector('[role=feed]');var len=function(l){return Array.from(l).slice(0,8).map(function(e){return e.innerText.length}).join(',')};return ['articles '+n('[role=article]')+' textlen '+len(document.querySelectorAll('[role=article]')),'feed '+n('[role=feed]')+' kids-textlen '+len(f?f.children:[]),'links '+Object.keys(m).slice(0,20).map(function(k){return k+' x'+m[k]}).join(' ; ')]})()";
fn waitPosts(ctx: *task.Ctx) !void { var left: u32 = 20; while (left > 0) : (left -= 1) { if ((try task.jsList(ctx, HAVE)).len > 0) return; std.Io.sleep(ctx.iozz, .fromMilliseconds(1000), .awake) catch return; } }
pub const Item = struct { u: []const u8 = "", a: []const u8 = "", t: []const u8 = "", f: u8 = 0 };
fn bodyKey(item: Item) u64 { var best: []const u8 = ""; var iter = std.mem.splitScalar(u8, item.t, '\n'); while (iter.next()) |line| { if (line.len > best.len) best = line; } return std.hash.Wyhash.hash(std.hash.Wyhash.hash(0, item.a), best); }
fn linkOf(aren: std.mem.Allocator, src: []const u8, item: Item) ![]const u8 { const pure = std.mem.trimEnd(u8, cutQuer(item.u), "/"); if (pure.len > 0 or item.f == 0 or !std.mem.startsWith(u8, src, "/groups/")) return pure; return std.fmt.allocPrint(aren, "{s}/posts/h{x}", .{ std.mem.trimEnd(u8, src, "/"), bodyKey(item) }); }
pub const Reco = struct { kind: []const u8, id: []const u8, url: []const u8, text: []const u8, src: []const u8, auth: []const u8, role: []const u8 };
fn cutQuer(urlz: []const u8) []const u8 { var endz: usize = 0; while (endz < urlz.len and urlz[endz] != '?' and urlz[endz] != '#') endz += 1; return urlz[0..endz]; }
pub fn idOfUrl(urlz: []const u8) []const u8 { const pure = cutQuer(urlz); for (KEYS) |key| { if (std.mem.find(u8, pure, key)) |at| { const rest = pure[at + key.len ..]; var endz: usize = 0; while (endz < rest.len and rest[endz] != '/') endz += 1; return rest[0..endz]; } } return ""; }
const UIZZ = [_][]const u8{ "Facebook", "Follow", "Theo dõi", "Like", "Thích", "Comment", "Bình luận", "Share", "Chia sẻ", "View more comments", "Xem thêm bình luận", "View more answers", "Write a public comment…", "Viết bình luận công khai…", "Write an answer…", "Viết câu trả lời…", "See more", "Xem thêm", "Active", "AI content" }; const ADSZ = [_][]const u8{ "Suggested for you", "Sponsored", "Gợi ý cho bạn", "Được tài trợ" };
fn uiLine(line: []const u8) bool { for (UIZZ) |word| { if (std.mem.eql(u8, line, word)) return true; } if (std.mem.startsWith(u8, line, "Accounts with a verified badge")) return true; if (line.len > 5) return false; for (line) |chr| { if (!std.ascii.isDigit(chr) and chr != '+') return false; } return true; }
fn isAdzz(text: []const u8) bool { var iter = std.mem.splitScalar(u8, text, '\n'); while (iter.next()) |line| { for (ADSZ) |word| { if (std.mem.eql(u8, line, word)) return true; } } return false; }
pub fn cleanText(aren: std.mem.Allocator, raws: []const u8) ![]const u8 { var flat: std.ArrayList(u8) = .empty; var posi: usize = 0; while (posi < raws.len) { if (posi + 1 < raws.len and raws[posi] == 0xCD and raws[posi + 1] == 0x8F) { posi += 2; continue; } try flat.append(aren, raws[posi]); posi += 1; } var outp: std.ArrayList(u8) = .empty; var last: []const u8 = ""; var iter = std.mem.splitScalar(u8, flat.items, '\n'); while (iter.next()) |part| { const line = std.mem.trim(u8, part, " \t\r\xc2\xa0"); if ((std.unicode.utf8CountCodepoints(line) catch 0) <= 1 or uiLine(line) or std.mem.eql(u8, line, last)) continue; if (outp.items.len > 0) try outp.append(aren, '\n'); try outp.appendSlice(aren, line); last = line; } return outp.items; }
fn headLine(raws: []const u8) []const u8 { var iter = std.mem.splitScalar(u8, raws, '\n'); return std.mem.trim(u8, iter.first(), " \t\r"); }
pub fn recoOf(aren: std.mem.Allocator, conf: cfgz.Conf, src: []const u8, raw: Item) !?Reco { var item = raw; item.t = try cleanText(aren, raw.t); if (isAdzz(item.t)) return null; item.a = headLine(std.mem.trim(u8, raw.a, " \t\r\n")); const pure = try linkOf(aren, src, item); if (pure.len == 0) return null; const text = std.mem.trim(u8, post.cutUtf8(std.mem.trim(u8, item.t, " \t\r\n"), conf.feed_text_maxz), " \t\r\n"); if (text.len == 0) return null; const urlz = if (std.mem.startsWith(u8, pure, "http")) pure else try std.fmt.allocPrint(aren, "{s}{s}", .{ conf.base_urlz_main, pure }); var idzz = idOfUrl(pure); if (idzz.len == 0) idzz = try std.fmt.allocPrint(aren, "{x}", .{std.hash.Wyhash.hash(0, urlz)}); return .{ .kind = CF.kind, .id = idzz, .url = urlz, .text = text, .src = src, .auth = std.mem.trim(u8, item.a, " \t\r\n"), .role = CF.role }; }
fn writeOut(ctx: *task.Ctx, body: []const u8) ![]const u8 { if (ctx.feedd.len == 0) return error.BadConfig; const cwdz = std.Io.Dir.cwd(); try cwdz.createDirPath(ctx.iozz, ctx.feedd); const fina = try std.fs.path.join(ctx.aren, &.{ ctx.feedd, try std.fmt.allocPrint(ctx.aren, "fb-{d}.jsonl", .{task.nowMs(ctx)}) }); const temp = try std.fmt.allocPrint(ctx.aren, "{s}{s}", .{ fina, CF.part }); try cwdz.writeFile(ctx.iozz, .{ .sub_path = temp, .data = body }); try cwdz.rename(temp, cwdz, fina, ctx.iozz); return fina; }
pub fn feedRun(ctx: *task.Ctx) !u32 { const conf = ctx.conf; if (conf.feed_path_list.len == 0) { task.say(ctx, "no feed_path_list set in the config", .{}); return 0; } var outp: std.ArrayList(u8) = .empty; var cntz: u32 = 0; var skpz: u32 = 0; var fail: ?anyerror = null; const expr = try std.fmt.allocPrint(ctx.aren, "{s}{d}{s}", .{ CF.pre, conf.feed_item_maxz, CF.pos });
for (conf.feed_path_list) |path| { task.visit(ctx, path) catch |err| { fail = err; break; }; try waitPosts(ctx); const here = try task.jsList(ctx, "[location.pathname]"); if (here.len == 0 or !std.mem.startsWith(u8, here[0], std.mem.trimEnd(u8, path, "/"))) { task.say(ctx, "skipped {s}: Facebook showed another page ({s})", .{ path, if (here.len > 0) here[0] else "?" }); continue; } const befo = cntz; var seen: std.StringHashMapUnmanaged(void) = .empty; var rnd: u32 = 0; while (rnd < CF.rnds and cntz - befo < conf.feed_item_maxz) : (rnd += 1) { if (rnd > 0) { _ = try task.jsList(ctx, CF.down); std.Io.sleep(ctx.iozz, .fromMilliseconds(CF.gapz), .awake) catch {}; } const rows = try task.jsList(ctx, expr); for (rows) |row| { const item = std.json.parseFromSliceLeaky(Item, ctx.aren, row, .{ .ignore_unknown_fields = true, .allocate = .alloc_always }) catch { if (rnd == 0) skpz += 1; continue; }; const rec = (try recoOf(ctx.aren, conf, path, item)) orelse { if (rnd == 0) skpz += 1; continue; }; if (seen.contains(rec.url) or cntz - befo >= conf.feed_item_maxz) continue; try seen.put(ctx.aren, rec.url, {}); try outp.appendSlice(ctx.aren, try std.json.Stringify.valueAlloc(ctx.aren, rec, .{})); try outp.append(ctx.aren, '\n'); cntz += 1; } } if (cntz == befo) { for (try task.jsList(ctx, DIAG)) |line| task.say(ctx, "layout {s}: {s}", .{ path, line }); } }
if (cntz > 0 and (ctx.mode == .live or ctx.mode == .force)) { const where = try writeOut(ctx, outp.items); task.say(ctx, "wrote {d} records to {s} ({d} skipped)", .{ cntz, where, skpz }); } else task.say(ctx, "{d} records, {d} skipped{s}", .{ cntz, skpz, if (cntz > 0) " | add --live to write them for scra" else "" }); if (fail) |err| return err; return cntz; }
